class Solution:

	def solver(self, x, y):
		if x < 0 or x >= self.row or y < 0 or (y >= self.col) or (grid[x][y] == 'O'):
			return 0
		grid[x][y] = 'O'
		for (x1, y1) in [[-1, 0], [0, -1], [0, 1], [1, 0]]:
			self.solver(x + x1, y + y1)

	def xShape(self, grid):
		(self.row, self.col, area) = (len(grid), len(grid[0]), 0)
		for i in range(self.row):
			for j in range(self.col):
				if grid[i][j] == 'X':
					self.solver(i, j)
					area += 1
		return area
